function onLocationFound(e) {
    var lat = e.latlng.lat;
    var lng = e.latlng.lng;
    L.marker(e.latlng, {
        color: 'blue',
        fillColor: 'blue',
        fillOpacity: 0.5,
      }).addTo(map).bindPopup(`Twoja pozycja: ${lat > 0 ? `${lat}&deg;N` : `${lat}&deg;S`} ${lng > 0 ? `${lng}&deg;E` : `${lng}&deg;W`}`);
  }

function onLocationError(e) {
    alert(e.mesage);
  }

